CREATE TABLE IF NOT EXISTS cj_profiles(business_id TEXT PRIMARY KEY REFERENCES portfolio_businesses(id),origin TEXT NOT NULL,details TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',revision INTEGER NOT NULL DEFAULT 1,approved_by TEXT,approved_at TEXT);
CREATE TABLE IF NOT EXISTS cj_sources(business_id TEXT NOT NULL REFERENCES cj_profiles(business_id),id TEXT NOT NULL,url TEXT NOT NULL,status TEXT NOT NULL,checked_day TEXT NOT NULL,expires_day TEXT NOT NULL,excerpt TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(business_id,id));
CREATE TABLE IF NOT EXISTS cj_cases(business_id TEXT NOT NULL,deal_id TEXT NOT NULL,entry_key TEXT NOT NULL,interest TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,deal_id),UNIQUE(business_id,entry_key),FOREIGN KEY(business_id,deal_id) REFERENCES scm_deals(business_id,id));
CREATE TABLE IF NOT EXISTS cj_routes(business_id TEXT NOT NULL,deal_id TEXT NOT NULL,kind TEXT NOT NULL,agent TEXT NOT NULL,task_id TEXT NOT NULL REFERENCES tasks(id),reason TEXT NOT NULL,created_at TEXT NOT NULL,PRIMARY KEY(business_id,deal_id,kind,agent),FOREIGN KEY(business_id,deal_id) REFERENCES cj_cases(business_id,deal_id));
CREATE TABLE IF NOT EXISTS cj_requests(business_id TEXT NOT NULL,deal_id TEXT NOT NULL,entry_key TEXT NOT NULL,booking_id TEXT NOT NULL,PRIMARY KEY(business_id,entry_key),FOREIGN KEY(business_id,deal_id) REFERENCES cj_cases(business_id,deal_id),FOREIGN KEY(business_id,booking_id) REFERENCES scm_bookings(business_id,id));
CREATE TABLE IF NOT EXISTS cj_work_inputs(task_id TEXT PRIMARY KEY REFERENCES tasks(id),business_id TEXT NOT NULL REFERENCES cj_profiles(business_id),profile_fingerprint TEXT NOT NULL,source_refs TEXT NOT NULL,created_at TEXT NOT NULL);
